export function translateFormUi(language, englishText) {
  if (!englishText || typeof englishText !== 'string') return englishText || '';
  if (language === 'zh') return FORM_UI_ZH[englishText] || englishText;
  if (language === 'es') return FORM_UI_ES[englishText] || englishText;
  return englishText;
}
